WITH flattened AS (SELECT id, created_at, coupon_codes, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW EXPLODE(items) li AS elem), flattened_carts AS (SELECT id, created_at, qty, price, promo, value FROM flattened LATERAL VIEW OUTER EXPLODE(coupon_codes) t AS value), cleaned AS (SELECT *, TRIM(value) AS clean_value, COALESCE(promo, 'DIRECT') AS promo_filled FROM flattened_carts WHERE value IS NOT DISTINCT FROM 'VIP' AND promo = 'BUNDLE'), base AS (SELECT created_at, price, promo, value, clean_value, promo_filled, qty - price AS qty_minus_price FROM cleaned WHERE created_at >= TIMESTAMP '2025-03-02 01:00:00') SELECT created_at, promo, value, clean_value, promo_filled, qty_minus_price, CASE WHEN promo RLIKE '^(SPRING10|WELCOME5)$' THEN 'EXTENDED' WHEN promo RLIKE '^(VIP|BUNDLE)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS promo_zone FROM base ORDER BY value DESC NULLS LAST
